        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin ipt_isuexerRnd_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        selfVar.select()
        /* sdd-asis-lifecycle:end */

